package android.database.sqlite;
import android.database.Cursor;import android.content.ContentValues;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
public final class SQLiteDatabase implements AutoCloseable{
 public static final int CONFLICT_IGNORE=4,CONFLICT_REPLACE=5;
 private final Process process;private final BufferedReader input;private final PrintWriter output;private boolean transaction,success;
 public SQLiteDatabase(String path){try{process=new ProcessBuilder("python3",System.getProperty("ledger.bridge"),path).redirectError(ProcessBuilder.Redirect.INHERIT).start();input=new BufferedReader(new InputStreamReader(process.getInputStream(),StandardCharsets.UTF_8));output=new PrintWriter(new OutputStreamWriter(process.getOutputStream(),StandardCharsets.UTF_8),true);}catch(Exception e){throw new RuntimeException(e);}}
 private String enc(Object x){if(x==null)return "N";if(x instanceof Number)return "I"+x;return "S"+Base64.getEncoder().encodeToString(String.valueOf(x).getBytes(StandardCharsets.UTF_8));}
 private Object dec(String s){if(s.equals("N"))return null;if(s.startsWith("I"))return Long.valueOf(s.substring(1));return new String(Base64.getDecoder().decode(s.substring(1)),StandardCharsets.UTF_8);}
 private synchronized Cursor request(String sql,Object[] args){try{StringBuilder line=new StringBuilder("SQL\t"+Base64.getEncoder().encodeToString(sql.getBytes(StandardCharsets.UTF_8)));if(args!=null)for(Object a:args)line.append('\t').append(enc(a));output.println(line);String head=input.readLine();if(head==null)throw new IOException("Bridge closed");String[] h=head.split("\t");if(h[0].equals("ERR"))throw new IllegalStateException(new String(Base64.getDecoder().decode(h[1]),StandardCharsets.UTF_8)+" SQL="+sql);if(h[0].equals("OK"))return new Cursor(new String[0],new Object[0][]);int cols=Integer.parseInt(h[1]),count=Integer.parseInt(h[2]);String[] raw=input.readLine().split("\t",-1),names=new String[cols];for(int i=0;i<cols;i++)names[i]=(String)dec(raw[i]);Object[][] rows=new Object[count][cols];for(int j=0;j<count;j++){raw=input.readLine().split("\t",-1);for(int i=0;i<cols;i++)rows[j][i]=dec(raw[i]);}return new Cursor(names,rows);}catch(IOException e){throw new RuntimeException(e);}}
 public void execSQL(String sql){request(sql,null);}public void execSQL(String sql,Object[] args){request(sql,args);}public Cursor rawQuery(String sql,String[] args){return request(sql,args);}
 public void beginTransaction(){if(transaction)throw new IllegalStateException("nested transaction in harness");execSQL("BEGIN IMMEDIATE");transaction=true;success=false;}public void setTransactionSuccessful(){success=true;}public void endTransaction(){execSQL(success?"COMMIT":"ROLLBACK");transaction=false;success=false;}
 public long insertWithOnConflict(String table,String nullColumn,ContentValues v,int conflict){String cols=String.join(",",v.values.keySet()),marks=String.join(",",Collections.nCopies(v.values.size(),"?"));execSQL("INSERT "+(conflict==CONFLICT_IGNORE?"OR IGNORE ":conflict==CONFLICT_REPLACE?"OR REPLACE ":"")+"INTO "+table+"("+cols+") VALUES("+marks+")",v.values.values().toArray());try(Cursor c=rawQuery("SELECT changes(),last_insert_rowid()",null)){c.moveToFirst();return c.getLong(0)==0?-1:c.getLong(1);}}
 public long insertOrThrow(String table,String nullColumn,ContentValues v){return insertWithOnConflict(table,nullColumn,v,0);}
 public int update(String table,ContentValues v,String where,String[] args){List<Object> all=new ArrayList<>(v.values.values());if(args!=null)Collections.addAll(all,args);List<String> set=new ArrayList<>();for(String k:v.values.keySet())set.add(k+"=?");execSQL("UPDATE "+table+" SET "+String.join(",",set)+" WHERE "+where,all.toArray());try(Cursor c=rawQuery("SELECT changes()",null)){c.moveToFirst();return c.getInt(0);}}
 public void close(){output.println("QUIT");try{process.waitFor();input.close();output.close();}catch(Exception e){throw new RuntimeException(e);}}
}

